```python
from datetime import datetime, date, timedelta

def sowing_date(last_frost_date) -> str:
    """
    마지막 서리 날짜로부터 14일(7 + 7일) 뒤를 파종 권장일로 계산하여 ISO 날짜 문자열로 반환합니다.

    :param last_frost_date: 날짜 문자열(YYYY-MM-DD 형식 등) 또는 date/datetime 객체
    :return: ISO 형식의 파종 권장일 문자열 (YYYY-MM-DD)
    :raises ValueError: 입력이 날짜 형식이 아니거나 유효하지 않은 날짜인 경우
    """
    days_to_add = 7 + 7

    if isinstance(last_frost_date, datetime):
        base_date = last_frost_date.date()
    elif isinstance(last_frost_date, date):
        base_date = last_frost_date
    elif isinstance(last_frost_date, str):
        try:
            base_date = datetime.fromisoformat(last_frost_date).date()
        except ValueError:
            raise ValueError("입력이 올바른 날짜 형식이 아닙니다.")
    else:
        raise ValueError("입력이 올바른 날짜 형식이 아닙니다.")

    recommended_date = base_date + timedelta(days=days_to_add)
    return recommended_date.isoformat()
```

```python
def voltage_range(voltages):
    valid_voltages = []
    for v in voltages:
        if isinstance(v, bool):
            continue
        try:
            valid_voltages.append(float(v))
        except (ValueError, TypeError):
            continue

    if not valid_voltages:
        return None

    return min(valid_voltages), max(valid_voltages)
```

```javascript
function validateObservation(record) {
  // 24 * 60 = 1440

  // species가 빈 문자열인 경우 false 반환
  if (record.species === "") {
    return false;
  }

  let time = record.time;

  // 시간 값이 없거나 문자열이 아니거나 HH:MM 형식(5글자, 가운데 콜론)이 아니면 false 반환
  if (!time || typeof time !== "string" || time.length !== 5 || time[2] !== ":") {
    return false;
  }

  // 시와 분 추출
  let hourString = time.substring(0, 2);
  let minuteString = time.substring(3, 5);

  let hour = Number(hourString);
  let minute = Number(minuteString);

  // 숫자로 변환할 수 없는 경우 false 반환
  if (isNaN(hour) || isNaN(minute)) {
    return false;
  }

  // 시(00~23) 검사
  if (hour < 0 || hour > 23) {
    return false;
  }

  // 분(00~59) 검사
  if (minute < 0 || minute > 59) {
    return false;
  }

  return true;
}
```

